      "forbidden": ["纯粹玄学", "机械降神", "无逻辑的鬼魂"]
    }
  },
  "selected_recipe": {
    "x_axis_mode_id": "B11",
    "x_axis_mode_name": "谜",
    "y_axis_tags": ["刑侦悬疑", "规则怪谈", "克苏鲁"],
    "reaction_strength": "✷",
