        "chapter_number": 2,
        "chapter_title": "第二具尸体",
        "core_event": "通灵会另一成员死亡，死状相同。沈翊发现死者试图遵守规则却失败。",
        "emotional_tone": "紧张、压抑",
        "key_scenes": ["通灵会现场勘查", "陆思诚审讯嫌疑人", "沈翊发现规则3和5的逻辑矛盾"]
      },
      {
        "chapter_number": 3,
        "chapter_title": "1842年的幽灵",
        "core_event": "林婉在档案馆找到一份1842年的英文残卷，上面记录了相同的规则。",
        "emotional_tone": "神秘、历史厚重感",
        "key_scenes": ["档案馆密谈", "解读残卷", "发现'Project Siren'代号"]
      }
    ],
    "turning_point": "沈翊在显微镜下观察墙纸样本，产生强烈的幻觉（看到深海），意识到这不是简单的谋杀，而是某种生化或心理武器。"
  },
  "act_two": {
    "description": "调查深入，沈翊发现规则是'模因病毒'，自己开始出现感染症状（执行第六条）。",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "逻辑陷阱",
        "core_event": "沈翊推导出规则3和5的互斥是为了制造极度认知失调，诱发大脑产生特定频率。",
        "emotional_tone": "烧脑、焦虑",
        "key_scenes": ["沈翊的推理独白", "陆思诚遭遇袭击", "沈翊第一次出现呼吸困难"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "第六条规则",
        "core_event": "沈翊发现自己无意识地在憋气（或过度换气），对应规则6'不要停止流动'。",
        "emotional_tone": "惊悚、自我怀疑",
        "key_scenes": ["沈翊照镜子发现异常", "查阅医学资料无果", "意识到自己已入局"]
      },
      {
        "chapter_number": 6,
        "chapter_title": "塞壬计划",
